/**
 * Nodo n8n: "0. Preparar publicaciones queued"
 * Tipo: Code (JavaScript, "Run Once for All Items")
 *
 * Toma las publications recién creadas por Capa 5 (status='queued') y las
 * deja listas para publicar: valida que la cuenta esté conectada, arma el
 * caption final (caption + hashtags), calcula scheduled_at respetando
 * timezone del cliente y espaciado mínimo entre publicaciones.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

const MAX_CAPTION_LENGTH = 2200;

// Convierte "año/mes/día/hora local en timeZone" a un Date UTC exacto,
// sin hardcodear el offset (que cambia con horario de verano). Es un
// truco estándar: formateamos un UTC tentativo EN timeZone, medimos la
// diferencia contra lo que queríamos, y corregimos.
// Limitación conocida: en el día exacto de un cambio de horario de
// verano el resultado puede quedar corrido en 1h -- aceptable para una
// heurística de "mejor horario", no crítico.
const zonedHourToUtcDate = (year, month, day, hourLocal, timeZone) => {
  const tentative = new Date(Date.UTC(year, month - 1, day, hourLocal, 0, 0));
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const parts = Object.fromEntries(formatter.formatToParts(tentative).map((p) => [p.type, p.value]));
  const hour24 = Number(parts.hour) === 24 ? 0 : Number(parts.hour);
  const asIfLocal = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), hour24, Number(parts.minute), Number(parts.second));
  const diff = tentative.getTime() - asIfLocal;
  return new Date(tentative.getTime() + diff);
};

const localDateParts = (date, timeZone) => {
  const formatter = new Intl.DateTimeFormat('en-US', { timeZone, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit' });
  const parts = Object.fromEntries(formatter.formatToParts(date).map((p) => [p.type, p.value]));
  return { year: Number(parts.year), month: Number(parts.month), day: Number(parts.day) };
};

const computeScheduledAt = (client, lastPublication) => {
  const now = new Date();
  const { year, month, day } = localDateParts(now, client.timezone);
  let target = zonedHourToUtcDate(year, month, day, client.default_publish_hour_local, client.timezone);

  if (target <= now) {
    // ya pasó el horario de hoy -- programar para mañana a la misma hora local
    const tomorrow = localDateParts(new Date(target.getTime() + 24 * 3600 * 1000), client.timezone);
    target = zonedHourToUtcDate(tomorrow.year, tomorrow.month, tomorrow.day, client.default_publish_hour_local, client.timezone);
  }

  if (lastPublication) {
    const lastTime = new Date(lastPublication.scheduled_at || lastPublication.published_at).getTime();
    const minGapMs = client.min_hours_between_posts * 3600 * 1000;
    if (target.getTime() - lastTime < minGapMs) {
      target = new Date(lastTime + minGapMs);
    }
  }

  return target.toISOString();
};

const queued = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/publications?status=eq.queued&select=id,client_id,platform,render_id,caption_used,hashtags_used`,
  headers: SUPABASE_HEADERS,
  json: true,
});

const results = [];

for (const pub of queued) {
  const accounts = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/social_accounts?client_id=eq.${pub.client_id}&platform=eq.${pub.platform}&status=eq.active&select=id,publisher_provider,external_account_id`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  const account = accounts[0];

  if (!account) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
      headers: SUPABASE_HEADERS,
      body: { status: 'failed', error_message: `No hay una cuenta activa de ${pub.platform} conectada para este cliente`, updated_at: new Date().toISOString() },
      json: true,
    });
    results.push({ publication_id: pub.id, outcome: 'failed_no_account' });
    continue;
  }

  const finalCaption = [pub.caption_used || '', pub.hashtags_used || ''].filter(Boolean).join('\n\n').trim();

  if (!finalCaption) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
      headers: SUPABASE_HEADERS,
      body: { status: 'failed', error_message: 'Caption vacío -- no hay nada que publicar', updated_at: new Date().toISOString() },
      json: true,
    });
    results.push({ publication_id: pub.id, outcome: 'failed_empty_caption' });
    continue;
  }

  const truncatedCaption = finalCaption.length > MAX_CAPTION_LENGTH
    ? `${finalCaption.slice(0, MAX_CAPTION_LENGTH - 1)}…`
    : finalCaption;

  const clients = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/clients?id=eq.${pub.client_id}&select=timezone,default_publish_hour_local,min_hours_between_posts`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  const client = clients[0] || { timezone: 'America/Santiago', default_publish_hour_local: 10, min_hours_between_posts: 4 };

  const lastRows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/publications?client_id=eq.${pub.client_id}&platform=eq.${pub.platform}&status=in.(scheduled,published)&order=scheduled_at.desc.nullslast&limit=1&select=scheduled_at,published_at`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  const scheduledAt = computeScheduledAt(client, lastRows[0] || null);

  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
    headers: SUPABASE_HEADERS,
    body: {
      status: 'ready_to_schedule',
      caption_used: truncatedCaption,
      provider: account.publisher_provider,
      account_id: account.id,
      scheduled_at: scheduledAt,
      updated_at: new Date().toISOString(),
    },
    json: true,
  });

  results.push({ publication_id: pub.id, outcome: 'ready_to_schedule', scheduled_at: scheduledAt });
}

return results.map((r) => ({ json: r }));

/**
 * Nodo n8n: "1. Detectar publicaciones listas para publicar"
 * Tipo: Code (JavaScript, "Run Once for All Items")
 *
 * publications en 'ready_to_schedule', cuyo scheduled_at ya llegó, sin
 * lock activo, y (si es un reintento) cuyo next_attempt_at ya pasó.
 * Se arma la URL a mano en vez de usar la UI de query params de un nodo
 * HTTP nativo porque el filtro `or=()` de PostgREST (next_attempt_at
 * NULL o ya vencido) es más simple de construir con template strings que
 * peleando con esa UI.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

const nowIso = new Date().toISOString();

const query = [
  'status=eq.ready_to_schedule',
  `scheduled_at=lte.${encodeURIComponent(nowIso)}`,
  'locked_at=is.null',
  `or=(${encodeURIComponent(`next_attempt_at.is.null,next_attempt_at.lte.${nowIso}`)})`,
  'select=id,client_id,platform,render_id,account_id,provider,caption_used,retry_count',
  'order=scheduled_at.asc',
].join('&');

const rows = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/publications?${query}`,
  headers: SUPABASE_HEADERS,
  json: true,
});

return rows.map((r) => ({ json: r }));

/**
 * Nodo n8n: "2. Publicar (con lock)"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Reclama un lock atómico sobre la fila de `publications` antes de hacer
 * nada (idempotencia + evita publicar dos veces el mismo render si dos
 * ciclos del schedule se solapan), llama a publish-api, y guarda el
 * resultado. Reintentos con backoff exponencial simple para errores
 * transitorios (rate limit, red).
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY,
 * PUBLISH_API_URL, TELEGRAM_BOT_TOKEN, TELEGRAM_CHAT_ID
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};
const PUBLISH_API_URL = $env.PUBLISH_API_URL;
const TELEGRAM_BOT_TOKEN = $env.TELEGRAM_BOT_TOKEN;

const MAX_ATTEMPTS = 3;
const WORKER_ID = `n8n-capa6-${$execution.id}`;

const pub = $json;

const sendTelegram = async (chatId, text) => this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
  body: { chat_id: chatId, text },
  json: true,
});

// 1. Reclamar el lock -- PATCH condicional: solo pega si locked_at sigue
// NULL. Si la respuesta viene vacía, alguien más ya lo tomó -- se aborta
// sin tocar nada más.
const claimed = await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}&locked_at=is.null`,
  headers: SUPABASE_HEADERS,
  body: { locked_at: new Date().toISOString(), locked_by: WORKER_ID },
  json: true,
});

if (!Array.isArray(claimed) || claimed.length === 0) {
  return [{ json: { publication_id: pub.id, outcome: 'skipped_already_locked' } }];
}

// 2. Idempotencia real: si por lo que sea esta fila ya tiene
// external_post_id, ya se publicó -- no se vuelve a llamar al proveedor
// aunque el lock se haya podido tomar (ej. un estado inconsistente
// después de un fallo a mitad de camino).
const current = claimed[0];
if (current.external_post_id) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
    headers: SUPABASE_HEADERS,
    body: { locked_at: null, locked_by: null },
    json: true,
  });
  return [{ json: { publication_id: pub.id, outcome: 'already_published', external_post_id: current.external_post_id } }];
}

// 3. Traer el video y la cuenta destino.
const renders = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/renders?id=eq.${pub.render_id}&select=public_url,status`,
  headers: SUPABASE_HEADERS,
  json: true,
});
const render = renders[0];

const accounts = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/social_accounts?id=eq.${pub.account_id}&select=external_account_id,status`,
  headers: SUPABASE_HEADERS,
  json: true,
});
const account = accounts[0];

if (!render || render.status !== 'done' || !account || account.status !== 'active') {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
    headers: SUPABASE_HEADERS,
    body: {
      status: 'failed',
      error_message: !render || render.status !== 'done' ? 'El render asociado ya no está disponible' : 'La cuenta se desconectó después de programar la publicación',
      locked_at: null,
      locked_by: null,
      updated_at: new Date().toISOString(),
    },
    json: true,
  });
  return [{ json: { publication_id: pub.id, outcome: 'failed_missing_dependency' } }];
}

// 4. Publicar.
await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
  headers: SUPABASE_HEADERS,
  body: { status: 'publishing', updated_at: new Date().toISOString() },
  json: true,
});

const job = {
  publication_id: pub.id,
  client_id: pub.client_id,
  platform: pub.platform,
  provider: pub.provider,
  account_external_id: account.external_account_id,
  video_url: render.public_url,
  caption: pub.caption_used,
  scheduled_at: null, // publicación inmediata: n8n ya esperó hasta scheduled_at antes de tomar esta fila
};

let result;
try {
  result = await this.helpers.httpRequest({
    method: 'POST',
    url: `${PUBLISH_API_URL}/publish`,
    body: job,
    json: true,
  });
} catch (err) {
  result = { ok: false, status: 'rate_limited', error_message: `publish-api inaccesible: ${String(err)}`, retryable: true, provider_post_id: null, provider_status: null, published_at: null, scheduled_at: null };
}

// 5. Guardar resultado + liberar el lock.
if (result.ok && (result.status === 'published' || result.status === 'scheduled')) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
    headers: SUPABASE_HEADERS,
    body: {
      status: result.status,
      external_post_id: result.provider_post_id,
      provider_status: result.provider_status,
      published_at: result.published_at,
      error_message: null,
      locked_at: null,
      locked_by: null,
      updated_at: new Date().toISOString(),
    },
    json: true,
  });

  const chatIdRows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/clients?id=eq.${pub.client_id}&select=telegram_chat_id`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  const chatId = (chatIdRows[0] && chatIdRows[0].telegram_chat_id) || $env.TELEGRAM_CHAT_ID;
  const label = result.status === 'published' ? '🚀 Publicado' : '🗓️ Programado';
  await sendTelegram(chatId, `${label} en ${pub.platform} -- ID del proveedor: ${result.provider_post_id}`);

  return [{ json: { publication_id: pub.id, outcome: result.status } }];
}

// Fallo: decidir si reintenta o queda terminal.
const nextAttempts = (pub.retry_count || 0) + 1;
const isTerminal = !result.retryable || nextAttempts >= MAX_ATTEMPTS;
const backoffMinutes = Math.pow(3, nextAttempts); // 3, 9, 27 minutos

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
  headers: SUPABASE_HEADERS,
  body: {
    status: isTerminal ? 'failed' : 'ready_to_schedule',
    error_message: result.error_message,
    provider_status: result.provider_status,
    retry_count: nextAttempts,
    next_attempt_at: isTerminal ? null : new Date(Date.now() + backoffMinutes * 60 * 1000).toISOString(),
    locked_at: null,
    locked_by: null,
    updated_at: new Date().toISOString(),
  },
  json: true,
});

if (isTerminal) {
  const chatIdRows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/clients?id=eq.${pub.client_id}&select=telegram_chat_id`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  const chatId = (chatIdRows[0] && chatIdRows[0].telegram_chat_id) || $env.TELEGRAM_CHAT_ID;
  await sendTelegram(chatId, `❌ No se pudo publicar en ${pub.platform} después de ${nextAttempts} intentos.\nError: ${result.error_message}`);
}

return [{ json: { publication_id: pub.id, outcome: isTerminal ? 'failed' : 'retry_scheduled', attempt: nextAttempts } }];

/**
 * Nodo n8n: "3. Sweep locks vencidos"
 * Tipo: Code (JavaScript, "Run Once for All Items")
 *
 * Si una ejecución de "2. Publicar (con lock)" muere a mitad de camino
 * (n8n se reinicia, timeout, etc.), la fila queda con locked_at seteado
 * para siempre y nunca se vuelve a intentar. Esto libera locks de más de
 * 10 minutos -- mismo principio que los sweeps de Capa 4 y Capa 5.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const TIMEOUT_MINUTES = 10;
const cutoff = new Date(Date.now() - TIMEOUT_MINUTES * 60 * 1000).toISOString();

const stuck = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/publications?locked_at=lt.${encodeURIComponent(cutoff)}&select=id,locked_by`,
  headers: SUPABASE_HEADERS,
  json: true,
});

const results = [];

for (const pub of stuck) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/publications?id=eq.${pub.id}`,
    headers: SUPABASE_HEADERS,
    body: { locked_at: null, locked_by: null, updated_at: new Date().toISOString() },
    json: true,
  });
  results.push({ publication_id: pub.id, previously_locked_by: pub.locked_by });
}

return results.map((r) => ({ json: r }));
